    conn.execute(
        "INSERT INTO events (id, project, start_utc, end_utc) VALUES (?, ?, ?, ?)",
        (event_id, project, start_utc, end_utc),
    )
    conn.commit()
    return {"inserted": 1, "duplicates": 0}


def cmd_add(args):
    conn = open_db(args.db)
    try:
